import androidx.compose.runtime.Composable
import androidx.compose.runtime.ProvidableCompositionLocal
import androidx.compose.runtime.compositionLocalOf
import com.varabyte.kobweb.core.AppGlobals
import com.varabyte.kobweb.navigation.BasePath
import com.varabyte.kobweb.navigation.Router
import com.varabyte.kobweb.navigation.UpdateHistoryMode
import com.varabyte.kobweb.navigation.remove
import com.varabyte.kobweb.silk.defer.DeferringHost
import kotlin.Any
import kotlin.Suppress
import kotlin.Unit
import kotlinx.browser.document
import kotlinx.browser.window
import org.jetbrains.compose.web.renderComposable
import my.ym.ma_projects_wizard.components.layouts.MarkdownLayout as _my_ym_ma_projects_wizard_components_layouts_MarkdownLayout
import my.ym.ma_projects_wizard.components.layouts.PageLayout as _my_ym_ma_projects_wizard_components_layouts_PageLayout
import my.ym.ma_projects_wizard.pages.AboutPage as _my_ym_ma_projects_wizard_pages_AboutPage
import my.ym.ma_projects_wizard.pages.ConverterOfVdAndSvgPage as _my_ym_ma_projects_wizard_pages_ConverterOfVdAndSvgPage
import my.ym.ma_projects_wizard.pages.HomePage as _my_ym_ma_projects_wizard_pages_HomePage
import my.ym.ma_projects_wizard.pages.TodoPage as _my_ym_ma_projects_wizard_pages_TodoPage

private val LayoutScopeLocal: ProvidableCompositionLocal<Any?> = compositionLocalOf<Any?> { null }

@Composable
private fun <T : Any> currentLayoutScope(): T {
    @Suppress("UNCHECKED_CAST")
    return LayoutScopeLocal.current as? T
        ?: error("Unexpected between Page/Layout scope and the parent Layout which it is providing it. Please report this issue to the Kobweb developers.")
}

@Composable
private fun <T : Any> provideLayoutScope(layoutScope: T, content: @Composable () -> Unit) {
    androidx.compose.runtime.CompositionLocalProvider(LayoutScopeLocal provides layoutScope, content = content)
}

public fun main() {
    AppGlobals.initialize(mapOf("title" to "MA Projects Wizard"))
    BasePath.set("/MA-Projects-Wizard/")
    val router = Router()
    com.varabyte.kobweb.core.init.initKobweb(router) { ctx ->
        ctx.router.registerLayout(
            "my.ym.ma_projects_wizard.components.layouts.MarkdownLayout",
            parentLayoutId = "my.ym.ma_projects_wizard.components.layouts.PageLayout",
            initRouteMethod = { ctx ->
                my.ym.ma_projects_wizard.components.layouts.initMarkdownLayout(ctx)
            },
        ) { pageCtx, pageMethod -> 
            _my_ym_ma_projects_wizard_components_layouts_MarkdownLayout {
                pageMethod(pageCtx)
            }
        }
        ctx.router.registerLayout(
            "my.ym.ma_projects_wizard.components.layouts.PageLayout",
        ) { pageCtx, pageMethod -> 
            _my_ym_ma_projects_wizard_components_layouts_PageLayout(pageCtx) {
                provideLayoutScope(this) {
                    pageMethod(pageCtx)
                }
            }
        }
        ctx.router.register(
            "/",
            layoutId = "my.ym.ma_projects_wizard.components.layouts.PageLayout",
            initRouteMethod = { ctx ->
                my.ym.ma_projects_wizard.pages.initHomePage(ctx)
            },
        ) { pageCtx -> 
            _my_ym_ma_projects_wizard_pages_HomePage()
        }
        ctx.router.register(
            "/about",
            layoutId = "my.ym.ma_projects_wizard.components.layouts.MarkdownLayout",
            initRouteMethod = { ctx ->
                my.ym.ma_projects_wizard.pages.initAboutPage(ctx)
            },
        ) { pageCtx -> 
            _my_ym_ma_projects_wizard_pages_AboutPage()
        }
        ctx.router.register(
            "/converter-of-vd-and-svg",
            layoutId = "my.ym.ma_projects_wizard.components.layouts.PageLayout",
            initRouteMethod = { ctx ->
                my.ym.ma_projects_wizard.pages.initConverterOfVdAndSvgPage(ctx)
            },
        ) { pageCtx -> 
            _my_ym_ma_projects_wizard_pages_ConverterOfVdAndSvgPage()
        }
        ctx.router.register(
            "/todo",
            layoutId = "my.ym.ma_projects_wizard.components.layouts.MarkdownLayout",
            initRouteMethod = { ctx ->
                my.ym.ma_projects_wizard.pages.initTodoPage(ctx)
            },
        ) { pageCtx -> 
            _my_ym_ma_projects_wizard_pages_TodoPage()
        }

    }
    router.addRouteInterceptor {
        path = path.removeSuffix(".html").removeSuffix(".htm")
    }

    com.varabyte.kobweb.silk.init.additionalSilkInitialization = { ctx ->
        com.varabyte.kobweb.silk.init.initSilkWidgets(ctx)
        com.varabyte.kobweb.silk.init.initSilkWidgetsKobweb(ctx)
        ctx.theme.registerStyle("headline-text", my.ym.ma_projects_wizard.HeadlineTextStyle)
        ctx.theme.registerStyle("subheadline-text", my.ym.ma_projects_wizard.SubheadlineTextStyle)
        ctx.theme.registerStyle("nav-header", my.ym.ma_projects_wizard.components.sections.NavHeaderStyle)
        ctx.theme.registerStyle("nav-link", my.ym.ma_projects_wizard.components.sections.NavLinkStyle)
        ctx.theme.registerStyle("footer", my.ym.ma_projects_wizard.components.sections.FooterStyle)
        ctx.theme.registerStyle("page-content", my.ym.ma_projects_wizard.components.layouts.PageContentStyle)
        ctx.theme.registerStyle("markdown", my.ym.ma_projects_wizard.components.layouts.MarkdownStyle)
        ctx.theme.registerStyle("custom-interactive-card", my.ym.ma_projects_wizard.pages.CustomInteractiveCardStyle)
        ctx.theme.registerVariant("-circle", my.ym.ma_projects_wizard.CircleButtonVariant
        )
        ctx.theme.registerVariant("-uncolored", my.ym.ma_projects_wizard.UncoloredButtonVariant
        )
        ctx.theme.registerKeyframes("side-menu-slide-in", my.ym.ma_projects_wizard.components.sections.SideMenuSlideInAnim)
        my.ym.ma_projects_wizard.initTheme(ctx)
        my.ym.ma_projects_wizard.initSiteStyles(ctx)
        my.ym.ma_projects_wizard.initColorMode(ctx)
        my.ym.ma_projects_wizard.initStyles(ctx)
    }

    // Dedup any leading slashes after removing the origin, just in case someone typed
    // something like `https://site.com//about` by accident. If we pass `//about` into
    // `tryRoutingTo`, Kobweb will reject it as a protocol-relative URL; instead, we
    // want it to navigate to `/about`
    router.tryRoutingTo(BasePath.remove("/" + window.location.href.removePrefix(window.origin).trimStart('/')), UpdateHistoryMode.REPLACE)

    // For SEO, we may bake the contents of a page in at build time. However, we will
    // overwrite them the first time we render this page with their composable, dynamic
    // versions. Think of this as poor man's hydration :)
    // See also: https://en.wikipedia.org/wiki/Hydration_(web_development)
    val root = document.getElementById("_kobweb-root")!!
    while (root.firstChild != null) { root.removeChild(root.firstChild!!) }

    renderComposable(rootElementId = "_kobweb-root") {
        my.ym.ma_projects_wizard.AppEntry {
            router.renderActivePage { DeferringHost { it() } }
        }
    }
}
